items.promptMarkdown:
```js
// line 1
await db.$transaction(async (tx) => {
  // line 2
  const part = await tx.part.findUnique({ where: { sku } });
  // line 3
  if (part.onHand < qty) throw new InsufficientStock(sku);
  // line 4
  await tx.part.update({ where: { sku }, data: { onHand: part.onHand - qty } });
  // line 5
  await tx.shipment.create({ data: { sku, qty, orderId } });
});
```

Two requests each ship 3 units of a part with `onHand = 3`. Both succeed; stock ends at `0` and six units are shipped.

Which change fixes this?

solution.explanationMarkdown:
Lines 3 and 4 are separate statements, so two transactions can both pass line 3 before either runs line 4. Worse, line 4 writes `part.onHand - qty` — a value computed from the stale read — so the second write does not decrement, it *overwrites* with `0`.

```js
const { count } = await tx.part.updateMany({
  where: { sku, onHand: { gte: qty } },
  data:  { onHand: { decrement: qty } },
});
if (count === 0) throw new InsufficientStock(sku);
```

Both the condition and the arithmetic now happen inside the database, in one statement, so there is no window and no stale value. `count === 0` is the refusal.

Adding `CHECK (on_hand >= 0)` on top is still worth doing: it converts any future code path that gets this wrong from silent corruption into a loud failure.

solution.code:
function classifyAnomaly(trace) {
  const uncommitted = {};
  const lastRead = {};
  const committedSince = {};
  let phantom = false;
  let nonRepeatable = false;
  for (let i = 0; i < trace.length; i += 1) {
    const e = trace[i];
    if (e.op === 'write') {
      if (!uncommitted[e.tx]) uncommitted[e.tx] = [];
      uncommitted[e.tx].push(e.key);
    } else if (e.op === 'commit') {
      const keys = uncommitted[e.tx] || [];
      for (let j = 0; j < keys.length; j += 1) {
        committedSince[keys[j]] = true;
      }
      uncommitted[e.tx] = [];
    } else if (e.op === 'read' && e.tx === 'T1') {
      let dirty = false;
      const txs = Object.keys(uncommitted);
      for (let j = 0; j < txs.length; j += 1) {
        if (txs[j] === 'T1') continue;
        const keys = uncommitted[txs[j]];
        for (let k = 0; k < keys.length; k += 1) {
          if (keys[k] === e.key) dirty = true;
        }
      }
      if (dirty) return 'dirty-read';
      if (Object.prototype.hasOwnProperty.call(lastRead, e.key)) {
        if (lastRead[e.key] !== e.rows) {
          phantom = true;
        } else if (committedSince[e.key]) {
          nonRepeatable = true;
        }
      }
      lastRead[e.key] = e.rows;
      committedSince[e.key] = false;
    }
  }
  if (phantom) return 'phantom';
  if (nonRepeatable) return 'non-repeatable-read';
  return 'none';
}

grading.starterCode:
function classifyAnomaly(trace) {
  // Reports a non-repeatable read whenever T1 reads the same key twice.
  const seen = {};
  for (let i = 0; i < trace.length; i += 1) {
    const e = trace[i];
    if (e.op === 'read' && e.tx === 'T1') {
      if (seen[e.key]) return 'non-repeatable-read';
      seen[e.key] = true;
    }
  }
  return 'none';
}

items.promptMarkdown:
Shipping a multi-line order updates each part in turn:

```js
await db.$transaction(async (tx) => {
  for (const line of order.lines) {
    await tx.part.updateMany({
      where: { sku: line.sku, onHand: { gte: line.qty } },
      data:  { onHand: { decrement: line.qty } },
    });
  }
});
```

Under load, roughly one shipment in a few hundred fails with:

```
deadlock detected
DETAIL: Process 8821 waits for ShareLock on transaction 5512; blocked by process 8804.
        Process 8804 waits for ShareLock on transaction 5519; blocked by process 8821.
```

What is the cause, and what is the fix?

solution.explanationMarkdown:
Both requests ran `findUnique` before either ran `submission.create`, so both saw no receipt and both created an order. The unique constraint then caught the *second receipt* — but far too late, after order 5502 already existed and had been returned to the client.

The constraint is doing its job; the code is asking it the question at the wrong moment. Put the work and the receipt in one transaction so the insert either wins or rolls back everything with it:

```js
try {
  return await db.$transaction(async (tx) => {
    const order = await tx.order.create({ data });
    await tx.submission.create({ data: { userId, key, requestHash, response: { id: order.id } } });
    return { status: 201, body: { id: order.id } };
  });
} catch (e) {
  if (isUniqueViolation(e)) {
    const receipt = await db.submission.findUnique({ where: { userId_key: { userId, key } } });
    return { status: 200, body: receipt.response };   // the loser replays the winner
  }
  throw e;
}
```

The loser of the race rolls back its order and then returns the winner's stored response, so the client sees one order either way. Note the log also reveals a second problem: no `requestHash` is stored, so this endpoint cannot detect case 3 — the same key reused with different content.

solution.code:
function resolveSubmission(receipts, request) {
  let found = null;
  for (let i = 0; i < receipts.length; i += 1) {
    const r = receipts[i];
    if (r.userId === request.userId && r.key === request.key) {
      found = r;
      break;
    }
  }
  if (found === null) {
    return { outcome: 'new' };
  }
  if (found.requestHash === request.requestHash) {
    return { outcome: 'replay', response: found.response };
  }
  return { outcome: 'conflict', storedHash: found.requestHash };
}

