function resolveSubmission(receipts, request) {
  // Matches on the key alone and ignores the request hash.
  for (let i = 0; i < receipts.length; i += 1) {
    if (receipts[i].key === request.key) {
      return { outcome: 'replay', response: receipts[i].response };
    }
  }
  return { outcome: 'new' };
}

